new_library <- function(books) {
  lib <- new.env()
  lib$books <- books
  lib$loans <- list()
  lib
}
borrow <- function(lib, member, title) {
  if (!(title %in% lib$books)) return("없는 책")
  if (title %in% names(lib$loans)) return("대출 중")
  lib$loans[[title]] <- member
  "대출 완료"
}
loans_of <- function(lib, member) {
  titles <- names(lib$loans)[unlist(lib$loans) == member]
  if (is.null(titles)) character(0) else sort(titles)
}
